import{Utils}from"../utils.min.js?v=1.0.0";import Base_Component from"../component/base-component.min.js?v=1.0.0";let Product_Based_Shipping={extends:Base_Component,template:"#shipflex-product-based-shipping-feature-component",props:{featureData:{default:null,type:[null,Object]}},data(){return{calculation_value:"",calculate_basis:"fixed_amount",advanced_calculation_tiers:[],calculation_type:"per_unit_or_percentage",...shipflex_admin?.features?.["product-based-shipping"],...this.featureData}},computed:{component_data(){return JSON.parse(JSON.stringify(this.$data))},show_calculation_value(){return"fixed_amount"==this.calculate_basis||"fixed_amount"!=this.calculate_basis&&"advanced_calculation"!=this.calculation_type},calculation_metrics(){return shipflex_admin.calculation_metrics},calculation_type_label(){return this.get_calculation_type_label(this.calculate_basis)}},methods:{add_shipping_cost_range(){Array.isArray(this.advanced_calculation_tiers)||(this.advanced_calculation_tiers=[]),this.advanced_calculation_tiers.push({id:Utils.generate_uuid()})},duplicate_shipping_cost_range(a,t){this.advanced_calculation_tiers.splice(t,0,a)},delete_shipping_cost_range(a){this.advanced_calculation_tiers.splice(a,1)}}};export default Product_Based_Shipping;